===== AssignMembershipNumber =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns a newly built owner its {@code membershipNumber}, formatted
 * {@code <customerCode>-M<YY>} where YY is the last two digits of the owner's
 * registration date year (e.g. {@code NSW-1A2B3C4D-M26}). Runs after
 * {@link AssignCustomerCode} and {@link ApplyRegistrationDate} so both inputs are
 * set — the year segment therefore uses the adjusted business day — and before
 * {@link SaveOwner}, mutating the built owner in place so the number is stored and
 * returned with the owner.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
    }
}
===== ResolveRegistrationDate =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Resolves the effective registration date for a create request and publishes it as a
 * variable. The effective date is the one supplied in the request, or the server's current
 * date when omitted; either way, a weekend is rolled forward to the next business day (see
 * {@link BusinessDays}). Runs before {@link EnsureDailyLimit} and {@link ApplyRegistrationDate}
 * so the per-day limit counts against, and the built owner is stamped with, the same adjusted
 * business day — and so everything derived from it (e.g. the membership-number year segment)
 * uses the adjusted date.
 */
public class ResolveRegistrationDate {

    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
        LocalDate supplied = request.getRegistrationDate();
        LocalDate effective = supplied != null ? supplied : LocalDate.now();
        registrationDate.set(BusinessDays.rollForward(effective));
    }
}
===== BusinessDays =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/**
 * Business-day calendar rules for owner registration. A registration date must fall on a
 * business day; a Saturday, Sunday or listed public holiday rolls forward to the next
 * non-holiday weekday. Used when resolving the effective registration date
 * ({@link ResolveRegistrationDate}) so that the stored date, everything derived from it
 * (e.g. the membership number's year segment) and the per-day create limit all agree on
 * the adjusted business day.
 */
final class BusinessDays {

    /** Fixed public holidays that a registration date rolls past. */
    private static final Set<LocalDate> HOLIDAYS = Set.of(
            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
            LocalDate.parse("2026-12-28"));

    private BusinessDays() {
    }

    /** The given date, or the next business day when it falls on a weekend or holiday. */
    static LocalDate rollForward(LocalDate date) {
        while (!isBusinessDay(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private static boolean isBusinessDay(LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
    }
}
===== ApplyRegistrationDate =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Stamps a newly built owner with the effective registration date resolved by
 * {@link ResolveRegistrationDate}. Runs after {@link BuildOwner} and mutates the built
 * owner in place, overwriting whatever date the request body mapped in, so the owner is
 * stored and returned with the adjusted business day and later steps (e.g.
 * {@link AssignMembershipNumber}) derive their values from it.
 */
public class ApplyRegistrationDate {

    public void service(@Val Owner owner, @Val LocalDate registrationDate) {
        owner.setRegistrationDate(registrationDate);
    }
}
===== ValidateRegistrationDate =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Validates the optional owner {@code registrationDate}. The date is optional, so a null
 * value is left untouched; when supplied it must not be later than the server's current
 * date (otherwise a 400 via {@link FutureRegistrationDateException}). Runs before
 * {@link ResolveRegistrationDate} so a future date is rejected before it is rolled forward
 * to a business day or counted against the daily limit.
 */
public class ValidateRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied == null) {
            return;
        }
        LocalDate serverDate = LocalDate.now();
        if (supplied.isAfter(serverDate)) {
            throw new FutureRegistrationDateException(supplied, serverDate);
        }
    }
}
===== DailyRegistrations =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Counts how many owners are registered on a given day. The registration date is the
 * canonical "day an owner was created" in this domain (see {@link ResolveRegistrationDate}),
 * so this single primitive backs both the per-day create limit ({@link EnsureDailyLimit})
 * and the bulk-signup warning ({@link BulkSignup}).
 */
final class DailyRegistrations {

    private DailyRegistrations() {
    }

    /** The number of existing owners whose registration date equals {@code date}. */
    static long countOn(OwnerRepository ownerRepository, LocalDate date) {
        long count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (date.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        return count;
    }
}

