     1	package org.springframework.samples.petclinic.util;
     2	
     3	import java.util.Locale;
     4	import java.util.function.Predicate;
     5	
     6	/**
     7	 * The owner's customer-code identity, formatted {@code <REGION>-<HASH8>} where REGION is
     8	 * the owner's region (see {@link OwnerRegion}) and HASH8 is the first 8 upper-case hex
     9	 * characters of SHA-256 over the normalized telephone concatenated with the last name
    10	 * (e.g. {@code NSW-1A2B3C4D}). This is the single source of an owner's identity: the
    11	 * membership number, its check digit and the audit record are all built from it, and the
    12	 * locality is the REGION read back out of it.
    13	 */
    14	public final class CustomerCode {
    15	
    16	    /** Separator between the REGION and HASH8 segments. */
    17	    private static final String SEPARATOR = "-";
    18	
    19	    /** Number of leading hex characters of the digest kept as the HASH8 segment. */
    20	    private static final int HASH_LENGTH = 8;
    21	
    22	    private CustomerCode() {
    23	    }
    24	
    25	    /**
    26	     * The {@code <REGION>-<HASH8>} customer code for the given region and identity inputs.
    27	     *
    28	     * @param region    the owner's region, used verbatim as the REGION segment
    29	     * @param telephone the owner's normalized (E.164) telephone
    30	     * @param lastName  the owner's last name
    31	     */
    32	    public static String of(String region, String telephone, String lastName) {
    33	        return region + SEPARATOR + hash8(telephone, lastName);
    34	    }
    35	
    36	    /**
    37	     * A customer code unique among the already-taken codes: the given code itself when it
    38	     * does not collide, otherwise {@code <customerCode>-<n>} with the smallest {@code n} of
    39	     * 2 or more that is not taken.
    40	     *
    41	     * @param customerCode the computed {@code <REGION>-<HASH8>} code
    42	     * @param taken        tests whether a code is already in use by an existing owner
    43	     */
    44	    public static String deduplicate(String customerCode, Predicate<String> taken) {
    45	        if (!taken.test(customerCode)) {
    46	            return customerCode;
    47	        }
    48	        for (int n = 2; ; n++) {
    49	            String candidate = customerCode + SEPARATOR + n;
    50	            if (!taken.test(candidate)) {
    51	                return candidate;
    52	            }
    53	        }
    54	    }
    55	
    56	    /** The REGION segment of a customer code: everything before the first separator. */
    57	    public static String regionOf(String customerCode) {
    58	        int separator = customerCode.indexOf(SEPARATOR);
    59	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
    60	    }
    61	
    62	    /** First {@value #HASH_LENGTH} upper-case hex characters of SHA-256(telephone + lastName). */
    63	    private static String hash8(String telephone, String lastName) {
    64	        return Sha256.hex(telephone + lastName).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
    65	    }
    66	}
