     1	package org.springframework.samples.petclinic.util;
     2	
     3	import java.time.LocalDate;
     4	import java.time.temporal.ChronoUnit;
     5	
     6	import org.springframework.samples.petclinic.model.Owner;
     7	
     8	/**
     9	 * Scores an owner's membership points. The total starts at 0 and gains, independently:
    10	 * {@link #EMAIL_POINTS} when the owner has an email address, {@link #UNIQUE_NAME_POINTS}
    11	 * when the owner has no namesakes ({@code namesakeCount == 0}), {@link #HOUSEHOLD_POINTS}
    12	 * for a household of {@link #HOUSEHOLD_MIN} or more members, and {@link #TENURE_POINTS}
    13	 * once the owner's tenure — measured from its registration date — exceeds
    14	 * {@link #TENURE_DAYS} days. The score maps to a level via {@link MembershipLevel}.
    15	 */
    16	public final class MembershipPoints {
    17	
    18	    /** Points gained when the owner has an email address. */
    19	    public static final int EMAIL_POINTS = 2;
    20	
    21	    /** Points gained when the owner has no namesakes ({@code namesakeCount == 0}). */
    22	    public static final int UNIQUE_NAME_POINTS = 1;
    23	
    24	    /** Points gained for a household of {@link #HOUSEHOLD_MIN} or more members. */
    25	    public static final int HOUSEHOLD_POINTS = 2;
    26	
    27	    /** Household size that earns {@link #HOUSEHOLD_POINTS}. */
    28	    public static final int HOUSEHOLD_MIN = 3;
    29	
    30	    /** Points gained once tenure exceeds {@link #TENURE_DAYS} days. */
    31	    public static final int TENURE_POINTS = 3;
    32	
    33	    /** Days of tenure an owner must exceed to earn {@link #TENURE_POINTS}. */
    34	    public static final int TENURE_DAYS = 365;
    35	
    36	    private MembershipPoints() {
    37	    }
    38	
    39	    /** The membership points for the given owner as of today. */
    40	    public static int of(Owner owner) {
    41	        return of(owner, LocalDate.now());
    42	    }
    43	
    44	    /** The membership points for the given owner, with tenure measured as of {@code asOf}. */
    45	    public static int of(Owner owner, LocalDate asOf) {
    46	        int points = 0;
    47	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
    48	            points += EMAIL_POINTS;
    49	        }
    50	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
